function readPricing(res) {
  // tolerant reader: only require the fields we actually use
  if (typeof res.amount_cents !== 'number') {
    throw new Error('missing required field: amount_cents');
  }
  // unknown/extra fields are simply never accessed -> ignored
  return { amount: res.amount_cents };
}

const cases = [
  { name: 'extra-unknown-fields', res: { amount_cents: 500, currency: 'USD', _trace: 'x' } },
  { name: 'exact-shape', res: { amount_cents: 500 } },
  { name: 'missing-required', res: { price_minor_units: 500 } }
];

for (const c of cases) {
  try {
    readPricing(c.res);
    console.log(c.name + ': PASS');
  } catch (e) {
    console.log(c.name + ': FAIL (' + e.message + ')');
  }
}
